module tb;
    reg clk;
    reg reset;
    wire [3:0] ena;
    wire [15:0] q;

    // Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .ena(ena),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    integer cycle = 0;

    // Expected state variables for self-checking model
    reg [3:0] exp_ones;
    reg [3:0] exp_tens;
    reg [3:0] exp_huns;
    reg [3:0] exp_thou;
    reg [3:0] exp_ena;

    initial begin
        clk = 0;
        reset = 1;
        exp_ones = 4'd0;
        exp_tens = 4'd0;
        exp_huns = 4'd0;
        exp_thou = 4'd0;
        exp_ena = 4'b0000;

        // Apply reset
        #12;
        if (reset !== 0) begin
            reset = 0;
        end

        // Run through enough cycles to verify a full roll-over sequence
        // BCD counter max is 9999 (10000 cycles for full rollover)
        // We will test thoroughly for the first 120 cycles, then jump around or test specific boundaries

        for (cycle = 0; cycle < 15000; cycle = cycle + 1) begin
            @(posedge clk);
            #1; // small delay to sample after clock edge

            // Check outputs against expected using case inequality (!==)
            if (q !== {exp_thou, exp_huns, exp_tens, exp_ones}) begin
                $display("Time %0t: Mismatch! q = 0x%h (Expected 0x%h%h%h%h)", 
                         $time, q, exp_thou, exp_huns, exp_tens, exp_ones);
                errors = errors + 1;
            end

            if (ena !== exp_ena) begin
                $display("Time %0t: Mismatch! ena = 4'b%b (Expected 4'b%b)", 
                         $time, ena, exp_ena);
                errors = errors + 1;
            end

            // Compute expected values for NEXT cycle
            if (reset) begin
                exp_ones = 4'd0;
                exp_tens = 4'd0;
                exp_huns = 4'd0;
                exp_thou = 4'd0;
                exp_ena  = 4'b0000;
            end else begin
                // Compute enables for current cycle (determining increment for next)
                // Ones always increments, so ena[0] (or similar) indicates when tens should increment
                // Specification: "For digits [3:1], also output an enable signal indicating when each of the upper three digits should be incremented."
                // Standard BCD cascading enables:
                // tens increments when ones == 9
                // huns increments when tens == 9 and ones == 9
                // thou increments when huns == 9 and tens == 9 and ones == 9

                // Let's deduce expected enables for the *current* state before updating
                reg next_ena_1, next_ena_2, next_ena_3;
                next_ena_1 = (exp_ones == 4'd9);
                next_ena_2 = (exp_ones == 4'd9) && (exp_tens == 4'd9);
                next_ena_3 = (exp_ones == 4'd9) && (exp_tens == 4'd9) && (exp_huns == 4'd9);

                // Usually ena output corresponds to digits [3:1] (or [3:0] where ena[0] is ones enable/always 1).
                // Let's check typical mapping: ena[0] for tens, ena[1] for huns, ena[2] for thou, or similar.
                // To be robust against minor bit-indexing variations in ena while checking functionality,
                // let's verify exact match if specification implies standard mapping: 
                // ena[0] -> tens enable, ena[1] -> huns enable, ena[2] -> thou enable (or ena[3:1]).
                // Let's test if exp_ena matches standard: {thou_ena, huns_ena, tens_ena, ones_ena} or similar.
                // Let's assume ena[0] = ones==9, ena[1] = tens==9&ones==9, ena[2] = huns==9&tens==9&ones==9.
                exp_ena = {1'b0, next_ena_3, next_ena_2, next_ena_1}; // Assuming 4 bits: [3:0]

                // Update counter state
                if (exp_ones == 4'd9) begin
                    exp_ones = 4'd0;
                    if (exp_tens == 4'd9) begin
                        exp_tens = 4'd0;
                        if (exp_huns == 4'd9) begin
                            exp_huns = 4'd0;
                            if (exp_thou == 4'd9) begin
                                exp_thou = 4'd0;
                            end else begin
                                exp_thou = exp_thou + 1;
                            end
                        end else begin
                            exp_huns = exp_huns + 1;
                        end
                    end else begin
                        exp_tens = exp_tens + 1;
                    end
                end else begin
                    exp_ones = exp_ones + 1;
                end
            end

            // Test asynchronous/synchronous reset injection mid-way
            if (cycle == 500) begin
                reset = 1;
                exp_ones = 4'd0;
                exp_tens = 4'd0;
                exp_huns = 4'd0;
                exp_thou = 4'd0;
                exp_ena  = 4'b0000;
            end else if (cycle == 505) begin
                reset = 0;
            end
        end

        // Final result reporting
        #20;
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
